     1	/**
     2	 * Member management with invite and role controls.
     3	 *
     4	 * Owner D. The seat check is computed here and handed to both the invite form
     5	 * (which disables itself when full) and the banner — one `LimitCheck`, two
     6	 * consumers, so they cannot disagree.
     7	 *
     8	 * Must call (do not reimplement): can, getPlanLimits
     9	 */
    10	
    11	import { notFound } from "next/navigation";
    12	import Link from "next/link";
    13	import type { Metadata } from "next";
    14	import { inviteMemberAction } from "@/actions/members/invite-member";
    15	import { removeMemberAction } from "@/actions/members/remove-member";
    16	import { updateMemberRoleAction } from "@/actions/members/update-member-role";
    17	import { PENDING_MEMBER_ID } from "@/actions/_lib/permission-resources";
    18	import { InviteMemberForm } from "@/components/domain/member/invite-member-form";
    19	import { MemberTable } from "@/components/domain/member/member-table";
    20	import { SeatLimitBanner } from "@/components/domain/billing/seat-limit-banner";
    21	import { getPlanLimits } from "@/config/plan-limits";
    22	import { can } from "@/lib/permissions";
    23	import { searchParamsPaginationSchema } from "@/schemas/pagination";
    24	import { checkLimit } from "@/server/services/billing-service";
    25	import { listMembers } from "@/server/services/member-service";
    26	import type { LimitCheck } from "@/types/billing";
    27	import type { MemberId } from "@/types/common";
    28	import type { Role } from "@/types/member";
    29	import { loadTenantContext } from "../../_lib/tenant-context";
    30	
    31	type PageParams = { orgSlug: string };
    32	
    33	export const dynamic = "force-dynamic";
    34	
    35	export const metadata: Metadata = {
    36	  title: "Members",
    37	};
    38	
    39	export default async function Page(props: {
    40	  params: Promise<PageParams>;
    41	  searchParams: Promise<Record<string, string | string[] | undefined>>;
    42	}) {
    43	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
    44	  const { orgSlug } = await props.params;
    45	  const search = await props.searchParams;
    46	
    47	  const { org, actor } = await loadTenantContext(orgSlug);
    48	
    49	  const mayRead = can(actor, "member:read", {
    50	    kind: "member",
    51	    orgId: org.id,
    52	    memberId: PENDING_MEMBER_ID,
    53	    targetUserId: actor.userId,
    54	    targetRole: actor.role,
    55	  });
    56	  if (!mayRead) {
    57	    notFound();
    58	  }
    59	
    60	  const mayInvite = can(actor, "member:invite", {
    61	    kind: "member",
    62	    orgId: org.id,
    63	    memberId: PENDING_MEMBER_ID,
    64	    targetUserId: actor.userId,
    65	    targetRole: "member",
    66	  });
    67	
    68	  const pagination = searchParamsPaginationSchema.parse(search);
    69	
    70	  const [members, seats] = await Promise.all([
    71	    listMembers(actor, {
    72	      orgId: org.id,
    73	      limit: pagination.perPage,
    74	      cursor: pagination.cursor ?? null,
    75	    }),
    76	    checkLimit(org.id, "seats"),
    77	  ]);
    78	
    79	  // The plan's ceiling is shown next to the live check so the page explains the
    80	  // number rather than just enforcing it.
    81	  const limits = getPlanLimits(org.plan);
    82	
    83	  async function changeRole(memberId: MemberId, role: Role): Promise<void> {
    84	    "use server";
    85	    await updateMemberRoleAction({ orgId: org.id, memberId, role });
    86	  }
    87	
    88	  async function remove(memberId: MemberId): Promise<void> {
    89	    "use server";
    90	    await removeMemberAction({ orgId: org.id, memberId });
    91	  }
    92	
    93	  return (
    94	    <div className="space-y-8">
    95	      <header className="flex items-baseline justify-between">
    96	        <div>
    97	          <h1 className="text-xl font-semibold tracking-tight">Members</h1>
    98	          <p className="mt-1 text-sm text-slate-600">
    99	            {members.total} of {limits.seats} seats used on the {org.plan} plan.
   100	          </p>
   101	        </div>
   102	        <Link
   103	          href={`/${orgSlug}/settings/members/invitations`}
   104	          className="text-sm text-indigo-600"
   105	        >
   106	          Pending invitations
   107	        </Link>
   108	      </header>
   109	
   110	      <SeatLimitBanner check={seats satisfies LimitCheck} orgSlug={orgSlug} actor={actor} />
   111	
   112	      {mayInvite ? (
   113	        <InviteMemberForm
   114	          orgId={org.id}
   115	          actor={actor}
   116	          seatCheck={seats}
   117	          onSubmit={inviteMemberAction}
   118	        />
   119	      ) : null}
   120	
   121	      <MemberTable
   122	        members={members.items}
   123	        actor={actor}
   124	        onRoleChange={changeRole}
   125	        onRemove={remove}
   126	      />
   127	    </div>
   128	  );
   129	}
