     1	import { z } from "zod";
     2	import { emailSchema, invitationIdSchema, orgIdSchema } from "./common";
     3	import { invitableRoleSchema } from "./role";
     4	
     5	/** Invitation lifecycle, kept apart from `member.ts` because the accept flow
     6	 *  runs unauthenticated (the token is the credential). */
     7	export const invitationTokenSchema = z
     8	  .string()
     9	  .min(32)
    10	  .max(128)
    11	  .regex(/^[A-Za-z0-9_-]+$/, "malformed invitation token");
    12	
    13	export const createInvitationSchema = z.object({
    14	  orgId: orgIdSchema,
    15	  email: emailSchema,
    16	  role: invitableRoleSchema,
    17	  expiresInDays: z.number().int().min(1).max(30).default(14),
    18	});
    19	
    20	export const resendInvitationSchema = z.object({
    21	  orgId: orgIdSchema,
    22	  invitationId: invitationIdSchema,
    23	});
    24	
    25	export const acceptInvitationTokenSchema = z.object({
    26	  token: invitationTokenSchema,
    27	});
    28	
    29	export type CreateInvitationInput = z.infer<typeof createInvitationSchema>;
    30	export type AcceptInvitationTokenInput = z.infer<
    31	  typeof acceptInvitationTokenSchema
    32	>;

