   117	export async function acceptInvitation(
   118	  userId: UserId,
   119	  input: AcceptInvitationTokenInput,
   120	): Promise<Member> {
   121	  const invitation = requireFound(
   122	    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
