   131	    throw new Error("That invitation has already been accepted");
   132	  }
   133	  if (invitation.expiresAt <= toIsoTimestamp(new Date())) {
   134	    throw new Error("That invitation has expired");
   135	  }
   136	
   137	  const existing = await memberRepo.findMember(invitation.orgId, userId);
   138	  if (existing) return existing;
   139	
   140	  const member = await memberRepo.insertMember(
   141	    invitation.orgId,
   142	    userId,
   143	    invitation.role,
   144	    invitation.invitedBy,
   145	  );
