    25	export async function acceptInvitationAction(raw: unknown): Promise<ActionResult<Member>> {
    26	  const parsed = acceptInvitationTokenSchema.safeParse(raw);
    27	  if (!parsed.success) {
    28	    return toActionResult(parsed.error);
    29	  }
    30	
    31	  try {
    32	    const principal = await getSessionPrincipal();
    33	    if (principal === null) {
    34	      throw new UnauthorizedActionError("Sign in before accepting an invitation.");
    35	    }
    36	
    37	    const member = await acceptInvitation(principal.userId, parsed.data);
    38	    await assertSeatAvailable(member);
    39	
    40	    return { ok: true, data: member, submittedAt: new Date().toISOString() };
    41	  } catch (error) {
    42	    return toActionResult(error);
    43	  }
    44	}
