    46	/**
    47	 * Confirms the newly created membership still fits the plan. Reading usage
    48	 * requires an actor inside the org, which only exists once the membership row
    49	 * has been written — hence the check runs after `acceptInvitation`.
    50	 */
    51	async function assertSeatAvailable(member: Member): Promise<void> {
    52	  const actor = await resolveActor(member.userId, member.orgId);
    53	  if (actor === null) {
    54	    throw new UnauthorizedActionError("That invitation is no longer valid.");
    55	  }
    56	
    57	  const summary = await getOrganizationSummary(actor, member.orgId);
    58	  const limits = getPlanLimits(summary.organization.plan);
    59	  if (summary.usage.seatsUsed > limits.seats) {
    60	    throw new PlanLimitError("seats", limits.seats, summary.usage.seatsUsed);
    61	  }
