     1	/**
     2	 * Renders react-email templates and 'sends' them by writing the draft to the log. No network egress.
     3	 */
     4	import { createLogger } from "@/lib/logger";
     5	
     6	export type OutgoingEmail = {
     7	  to: string;
     8	  subject: string;
     9	  html: string;
    10	  text: string;
    11	};
    12	
    13	export type RenderedEmail = { subject: string; html: string; text: string };
    14	
    15	export type EmailTemplate =
    16	  | "invite"
    17	  | "digest"
    18	  | "mention"
    19	  | "invoice"
    20	  | "welcome"
    21	  | "password-reset"
    22	  | "overdue";
    23	
    24	const logger = createLogger("email-service");
    25	
    26	/** Subject lines per template; the props fill in the bracketed parts. */
    27	const SUBJECTS: Readonly<Record<EmailTemplate, string>> = {
    28	  invite: "You have been invited to a Taskflow workspace",
    29	  digest: "Your Taskflow digest",
    30	  mention: "You were mentioned in Taskflow",
    31	  invoice: "Your Taskflow invoice",
    32	  welcome: "Welcome to Taskflow",
    33	  "password-reset": "Reset your Taskflow password",
    34	  overdue: "You have overdue issues",
    35	};
    36	
    37	/**
    38	 * "Sends" a message. Taskflow has no outbound mail transport by design — the
    39	 * corpus must build and run offline — so delivery means writing the draft to
    40	 * the structured log, where the dev tools tab surfaces it.
    41	 */
    42	export async function sendEmail(message: OutgoingEmail): Promise<void> {
    43	  logger.info("email.sent", {
    44	    to: message.to,
    45	    subject: message.subject,
    46	    bytes: message.html.length,
    47	  });
    48	}
    49	
    50	/**
    51	 * Renders a template to both an HTML and a plain-text body. The text half is
    52	 * derived from the HTML rather than written twice, so the two can never drift.
    53	 */
    54	export async function renderEmail(
    55	  template: EmailTemplate,
    56	  props: Readonly<Record<string, unknown>>,
    57	): Promise<RenderedEmail> {
    58	  const subject = subjectFor(template, props);
    59	  const html = renderBody(template, props);
    60	
    61	  return { subject, html, text: toPlainText(html) };
    62	}
    63	
    64	function subjectFor(
    65	  template: EmailTemplate,
    66	  props: Readonly<Record<string, unknown>>,
    67	): string {
    68	  const base = SUBJECTS[template];
    69	  const orgName = props.orgName;
    70	  return typeof orgName === "string" ? `${base} — ${orgName}` : base;
    71	}
    72	
    73	function renderBody(
    74	  template: EmailTemplate,
    75	  props: Readonly<Record<string, unknown>>,
    76	): string {
    77	  const rows = Object.entries(props)
    78	    .filter(([, value]) => value !== null && value !== undefined)
    79	    .map(
    80	      ([key, value]) =>
    81	        `<tr><td>${escapeHtml(key)}</td><td>${escapeHtml(String(value))}</td></tr>`,
    82	    )
    83	    .join("");
    84	
    85	  return [
    86	    `<html><body><h1>${escapeHtml(SUBJECTS[template])}</h1>`,
    87	    `<table>${rows}</table>`,
    88	    "</body></html>",
    89	  ].join("");
    90	}
    91	
    92	function toPlainText(html: string): string {
    93	  return html
    94	    .replace(/<\/(?:tr|h1|p|div)>/g, "\n")
    95	    .replace(/<[^>]+>/g, " ")
    96	    .replace(/[ \t]+/g, " ")
    97	    .replace(/\n\s+/g, "\n")
    98	    .trim();
    99	}
   100	
   101	function escapeHtml(value: string): string {
   102	  return value
   103	    .replace(/&/g, "&amp;")
   104	    .replace(/</g, "&lt;")
   105	    .replace(/>/g, "&gt;")
   106	    .replace(/"/g, "&quot;");
   107	}
     1	/**
     2	 * Renders a react-email component to the `{ subject, html, text }` triple
     3	 * `EmailService` sends.
     4	 *
     5	 * `EmailTemplate` is the closed vocabulary of templates; this module is the
     6	 * only place that maps a name to a component and to a subject line, so
     7	 * adding a template means touching exactly one switch in each direction.
     8	 */
     9	import { render } from "@react-email/components";
    10	import { createElement, type ReactElement } from "react";
    11	import { SITE_CONFIG } from "@/config/site";
    12	import type {
    13	  EmailTemplate,
    14	  RenderedEmail,
    15	} from "@/server/services/email-service";
    16	import { DigestEmail, type DigestEmailProps } from "./digest-email";
    17	import { InviteEmail, type InviteEmailProps } from "./invite-email";
    18	import { InvoiceEmail, type InvoiceEmailProps } from "./invoice-email";
    19	import { MentionEmail, type MentionEmailProps } from "./mention-email";
    20	import { OverdueEmail, type OverdueEmailProps } from "./overdue-email";
    21	import {
    22	  PasswordResetEmail,
    23	  type PasswordResetEmailProps,
    24	} from "./password-reset-email";
    25	import { WelcomeEmail, type WelcomeEmailProps } from "./welcome-email";
    26	
    27	type Props = Readonly<Record<string, unknown>>;
    28	
    29	/** Reads a string prop defensively — templates are fed loosely typed payloads. */
    30	function str(props: Props, key: string, fallback = ""): string {
    31	  const value = props[key];
    32	  return typeof value === "string" && value !== "" ? value : fallback;
    33	}
    34	
    35	function count(props: Props, key: string): number {
    36	  const value = props[key];
    37	  return Array.isArray(value) ? value.length : 0;
    38	}
    39	
    40	function elementFor(template: EmailTemplate, props: Props): ReactElement {
    41	  switch (template) {
    42	    case "invite":
    43	      return createElement(InviteEmail, props as unknown as InviteEmailProps);
    44	    case "digest":
    45	      return createElement(DigestEmail, props as unknown as DigestEmailProps);
    46	    case "mention":
    47	      return createElement(MentionEmail, props as unknown as MentionEmailProps);
    48	    case "invoice":
    49	      return createElement(InvoiceEmail, props as unknown as InvoiceEmailProps);
    50	    case "welcome":
    51	      return createElement(WelcomeEmail, props as unknown as WelcomeEmailProps);
    52	    case "password-reset":
    53	      return createElement(
    54	        PasswordResetEmail,
    55	        props as unknown as PasswordResetEmailProps,
    56	      );
    57	    case "overdue":
    58	      return createElement(OverdueEmail, props as unknown as OverdueEmailProps);
    59	  }
    60	}
    61	
    62	/** The subject line for a template, derived from the same props as the body. */
    63	export function subjectFor(template: EmailTemplate, props: Props): string {
    64	  switch (template) {
    65	    case "invite":
    66	      return `${str(props, "inviterName", "Someone")} invited you to ${str(
    67	        props,
    68	        "orgName",
    69	        SITE_CONFIG.name,
    70	      )}`;
    71	    case "digest": {
    72	      const total = count(props, "entries");
    73	      return `Your ${str(props, "orgName", SITE_CONFIG.name)} digest — ${total} update${
    74	        total === 1 ? "" : "s"
    75	      }`;
    76	    }
    77	    case "mention":
    78	      return `${str(props, "actorName", "Someone")} mentioned you on "${str(
    79	        props,
    80	        "issueTitle",
    81	        "an issue",
    82	      )}"`;
    83	    case "invoice":
    84	      return `Invoice ${str(props, "invoiceNumber", "")} for ${str(
    85	        props,
    86	        "orgName",
    87	        SITE_CONFIG.name,
    88	      )}`.replace(/\s+/g, " ");
    89	    case "welcome":
    90	      return `Welcome to ${SITE_CONFIG.name}`;
    91	    case "password-reset":
    92	      return `Reset your ${SITE_CONFIG.name} password`;
    93	    case "overdue": {
    94	      const total = count(props, "issues");
    95	      return `${total} overdue issue${total === 1 ? "" : "s"} in ${SITE_CONFIG.name}`;
    96	    }
    97	  }
    98	}
    99	
   100	/** Renders both the HTML and the plain-text alternative in one pass. */
   101	export async function renderTemplate(
   102	  template: EmailTemplate,
   103	  props: Props,
   104	): Promise<RenderedEmail> {
   105	  const element = elementFor(template, props);
   106	  const [html, text] = await Promise.all([
   107	    render(element),
   108	    render(element, { plainText: true }),
   109	  ]);
   110	
   111	  return { subject: subjectFor(template, props), html, text };
   112	}
     1	import type {
     2	  EventHandler,
     3	  TaskflowEventMap,
     4	  TaskflowEventPayload,
     5	  TaskflowEventType,
     6	  Unsubscribe,
     7	} from "@/types/event";
     8	
     9	/**
    10	 * In-process, typed publish/subscribe bus.
    11	 *
    12	 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
    13	 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
    14	 * every reactive concern `subscribe()`s at module init (see
    15	 * `src/server/services/event-registry.ts`). Handlers are isolated — one
    16	 * throwing handler never fails the emit or the sibling handlers.
    17	 */
    18	
    19	type HandlerSet = Set<EventHandler<TaskflowEventType>>;
    20	
    21	const handlers = new Map<TaskflowEventType, HandlerSet>();
    22	
    23	const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();
    24	
    25	/** Registers a handler for one event type. Call the return value to detach. */
    26	export function subscribe<K extends TaskflowEventType>(
    27	  type: K,
    28	  handler: EventHandler<K>,
    29	): Unsubscribe {
    30	  const set = handlers.get(type) ?? new Set();
    31	  set.add(handler as EventHandler<TaskflowEventType>);
    32	  handlers.set(type, set);
    33	  return () => {
    34	    set.delete(handler as EventHandler<TaskflowEventType>);
    35	  };
    36	}
    37	
    38	/** Registers a handler that detaches itself after the first delivery. */
    39	export function subscribeOnce<K extends TaskflowEventType>(
    40	  type: K,
    41	  handler: EventHandler<K>,
    42	): Unsubscribe {
    43	  const off = subscribe(type, (payload) => {
    44	    off();
    45	    return handler(payload);
    46	  });
    47	  return off;
    48	}
    49	
    50	/**
    51	 * Publishes an event to every subscriber. Resolves once all handlers settle;
    52	 * rejected handlers are reported to the error sinks, never rethrown.
    53	 */
    54	export async function emit<K extends TaskflowEventType>(
    55	  type: K,
    56	  payload: TaskflowEventPayload<K>,
    57	): Promise<void> {
    58	  const set = handlers.get(type);
    59	  if (!set || set.size === 0) return;
    60	
    61	  const results = await Promise.allSettled(
    62	    [...set].map(async (handler) => {
    63	      await (handler as EventHandler<K>)(payload);
    64	    }),
    65	  );
    66	
    67	  for (const result of results) {
    68	    if (result.status === "rejected") {
    69	      reportHandlerError(type, result.reason);
    70	    }
    71	  }
    72	}
    73	
    74	/** Fire-and-forget variant for call sites that must not await delivery. */
    75	export function emitAndForget<K extends TaskflowEventType>(
    76	  type: K,
    77	  payload: TaskflowEventPayload<K>,
    78	): void {
    79	  void emit(type, payload).catch((error: unknown) => {
    80	    reportHandlerError(type, error);
    81	  });
    82	}
    83	
    84	export function onHandlerError(
    85	  sink: (type: TaskflowEventType, error: unknown) => void,
    86	): Unsubscribe {
    87	  errorSinks.add(sink);
    88	  return () => {
    89	    errorSinks.delete(sink);
    90	  };
    91	}
    92	
    93	function reportHandlerError(type: TaskflowEventType, error: unknown): void {
    94	  for (const sink of errorSinks) {
    95	    try {
    96	      sink(type, error);
    97	    } catch {
    98	      // A failing error sink must never escalate.
    99	    }
   100	  }
   101	}
   102	
   103	/** Number of live subscribers for an event; used by tests and diagnostics. */
   104	export function subscriberCount(type: TaskflowEventType): number {
   105	  return handlers.get(type)?.size ?? 0;
   106	}
   107	
   108	/** Detaches every handler. Test-only — never call from application code. */
   109	export function resetEventBus(): void {
   110	  handlers.clear();
   111	  errorSinks.clear();
   112	}
   113	
   114	export type { TaskflowEventMap, TaskflowEventType, Unsubscribe };
