    93	  return html
    94	    .replace(/<\/(?:tr|h1|p|div)>/g, "\n")
    95	    .replace(/<[^>]+>/g, " ")
    96	    .replace(/[ \t]+/g, " ")
    97	    .replace(/\n\s+/g, "\n")
    98	    .trim();
