  1	import type { Actor, Role } from "@/types/member";
  2	import { ROLE_RANK } from "@/types/member";
  3	import type {
  4	  PermissionAction,
  5	  PermissionDecision,
  6	  PermissionResource,
  7	} from "@/types/permission";
  8	
  9	/**
 10	 * The single authorization entry point for Taskflow.
 11	 *
 12	 * Every Server Action, service method, Route Handler and permission-sensitive
 13	 * UI component funnels through `can()`. Nothing else may branch on
 14	 * `actor.role` directly — if you find yourself writing `role === "admin"`,
 15	 * add an action to `PermissionAction` and a row to `ROLE_MATRIX` instead.
 16	 *
 17	 * Decision order:
 18	 *   1. cross-tenant guard (`actor.orgId` must equal `resource.orgId`)
 19	 *   2. platform staff bypass
 20	 *   3. role matrix lookup
 21	 *   4. ownership escalations (authors edit their own issues/comments)
 22	 */
 23	
 24	/** Minimum role required for each action, before ownership escalations. */
 25	export const ROLE_MATRIX: Readonly<Record<PermissionAction, Role>> = {
 26	  "org:read": "viewer",
 27	  "org:update": "admin",
 28	  "org:delete": "owner",
 29	  "org:manage_billing": "owner",
 30	  "org:manage_flags": "admin",
 31	  "member:read": "viewer",
 32	  "member:invite": "admin",
 33	  "member:update_role": "admin",
 34	  "member:remove": "admin",
 35	  "project:create": "member",
 36	  "project:read": "viewer",
 37	  "project:update": "member",
 38	  "project:archive": "admin",
 39	  "project:delete": "owner",
 40	  "issue:create": "member",
 41	  "issue:read": "viewer",
 42	  "issue:update": "member",
 43	  "issue:assign": "member",
 44	  "issue:archive": "member",
 45	  "issue:delete": "admin",
 46	  "comment:create": "member",
 47	  "comment:read": "viewer",
 48	  "comment:update": "member",
 49	  "comment:delete": "admin",
 50	  "activity:read": "member",
 51	  "activity:export": "admin",
 52	  "notification:read": "viewer",
 53	  "notification:manage": "viewer",
 54	  "webhook:manage": "admin",
 55	};
 56	
 57	/** Actions an actor may perform on their own content regardless of role rank. */
 58	const OWNERSHIP_ESCALATIONS: Readonly<Partial<Record<PermissionAction, true>>> = {
 59	  "issue:update": true,
 60	  "issue:archive": true,
 61	  "comment:update": true,
 62	  "comment:delete": true,
 63	  "notification:manage": true,
 64	};
 65	
 66	function isOwnedByActor(
 67	  actor: Actor,
 68	  resource: PermissionResource,
 69	): boolean {
 70	  switch (resource.kind) {
 71	    case "issue":
 72	      return (
 73	        resource.authorId === actor.userId ||
 74	        resource.assigneeId === actor.userId
 75	      );
 76	    case "comment":
 77	      return resource.authorId === actor.userId;
 78	    case "project":
 79	      return resource.leadId === actor.userId;
 80	    case "notification":
 81	      return resource.recipientId === actor.userId;
 82	    case "member":
 83	      return resource.targetUserId === actor.userId;
 84	    default:
 85	      return false;
 86	  }
 87	}
