137	export class PermissionDeniedError extends Error {
138	  readonly code = "forbidden" as const;
139	
140	  constructor(
141	    readonly action: PermissionAction,
142	    readonly decision: PermissionDecision,
143	  ) {
144	    super(`Permission denied: ${action} on ${decision.resourceKind}`);
145	    this.name = "PermissionDeniedError";
146	  }
147	}
148	
149	/** Throwing variant of `can()` for service-layer guard clauses. */
150	export function assertCan(
151	  actor: Actor,
152	  action: PermissionAction,
153	  resource: PermissionResource,
154	): void {
155	  const decision = explain(actor, action, resource);
156	  if (!decision.allowed) {
157	    throw new PermissionDeniedError(action, decision);
158	  }
159	}
