 1	/**
 2	 * Resolves the request's `Actor` for a given org slug, or throws
 3	 * `unauthorized` / `forbidden`. Every Server Action starts here.
 4	 *
 5	 * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so
 6	 * this module is the seam between "there is an HTTP request with a cookie"
 7	 * and the rest of the app, which knows nothing about requests.
 8	 */
 9	import { getSessionPrincipal } from "@/lib/session";
10	import { assertOrgScope } from "@/lib/tenant";
11	import { findOrgById } from "@/server/repositories/organization-repository";
12	import { resolveActorForOrg } from "@/server/services/session-service";
13	import type { OrgId } from "@/types/common";
14	import type { Actor } from "@/types/member";
15	
16	/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */
17	export class UnauthorizedError extends Error {
18	  readonly code = "unauthorized" as const;
19	
20	  constructor(message = "Sign in to continue.") {
21	    super(message);
22	    this.name = "UnauthorizedError";
23	  }
24	}
25	
26	/** Thrown when the session is valid but has no membership in the target org. */
27	export class NoMembershipError extends Error {
28	  readonly code = "forbidden" as const;
29	
30	  constructor(readonly orgSlug: string) {
31	    super(`You are not a member of "${orgSlug}".`);
32	    this.name = "NoMembershipError";
33	  }
34	}
35	
36	/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */
37	export async function getActor(orgSlug: string): Promise<Actor> {
38	  const principal = await getSessionPrincipal();
39	  if (principal === null) throw new UnauthorizedError();
40	
41	  const actor = await resolveActorForOrg(principal, orgSlug);
42	  if (actor === null) throw new NoMembershipError(orgSlug);
43	
44	  return actor;
45	}
46	
47	/** Non-throwing variant, for layouts that render a signed-out state. */
48	export async function tryGetActor(orgSlug: string): Promise<Actor | null> {
49	  try {
50	    return await getActor(orgSlug);
51	  } catch (error) {
52	    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {
53	      return null;
54	    }
55	    throw error;
56	  }
57	}
58	
59	/**
60	 * The `Actor` for an org already identified by id — used by Route Handlers
61	 * that receive an `orgId` in the payload rather than a slug in the path. The
62	 * session's active org must match, which `assertOrgScope()` enforces.
63	 *
64	 * `resolveActorForOrg` keys off the org *slug*, so the id is translated here
65	 * with a single repository lookup rather than by widening that signature —
66	 * the slug is the only handle the session layer knows.
67	 */
68	export async function requireActorFor(orgId: OrgId): Promise<Actor> {
69	  const principal = await getSessionPrincipal();
70	  if (principal === null) throw new UnauthorizedError();
71	  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);
72	
73	  const org = await findOrgById(orgId);
74	  if (org === null) throw new NoMembershipError(orgId);
75	
76	  const actor = await resolveActorForOrg(principal, org.slug);
77	  if (actor === null) throw new NoMembershipError(org.slug);
78	
79	  assertOrgScope(actor, orgId);
80	  return actor;
81	}
 1	import type { OrgId, TenantScoped } from "@/types/common";
 2	import type { Actor } from "@/types/member";
 3	
 4	/**
 5	 * Multi-tenancy invariant helpers.
 6	 *
 7	 * Every repository query must be filtered by `org_id`, and every row that
 8	 * crosses a service boundary must be re-checked against the actor's org. These
 9	 * helpers are the only sanctioned way to express that — a hand-written
10	 * `if (row.orgId !== actor.orgId)` is a review failure.
11	 */
12	
13	export class TenantScopeError extends Error {
14	  readonly code = "tenant_scope_violation" as const;
15	
16	  constructor(
17	    readonly expectedOrgId: OrgId,
18	    readonly actualOrgId: OrgId,
19	  ) {
20	    super(
21	      `Tenant scope violation: expected org ${expectedOrgId}, got ${actualOrgId}`,
22	    );
23	    this.name = "TenantScopeError";
24	  }
25	}
26	
27	/** Throws unless `orgId` belongs to the actor's organization. */
28	export function assertOrgScope(actor: Actor, orgId: OrgId): void {
29	  if (actor.orgId !== orgId) {
30	    throw new TenantScopeError(actor.orgId, orgId);
31	  }
32	}
33	
34	/** Throws unless every supplied row belongs to the actor's organization. */
35	export function assertRowsInScope<T extends TenantScoped>(
36	  actor: Actor,
37	  rows: readonly T[],
38	): void {
39	  for (const row of rows) {
40	    assertOrgScope(actor, row.orgId);
41	  }
42	}
43	
44	/** Non-throwing predicate, for filtering rather than failing. */
45	export function isInOrgScope(actor: Actor, row: TenantScoped): boolean {
46	  return row.orgId === actor.orgId;
47	}
48	
49	/** Narrows a nullable row to one the actor may see; `null` otherwise. */
50	export function scopedOrNull<T extends TenantScoped>(
51	  actor: Actor,
52	  row: T | null | undefined,
53	): T | null {
54	  if (!row) return null;
55	  return row.orgId === actor.orgId ? row : null;
56	}
57	
58	/**
59	 * Wraps an arbitrary filter object with the actor's `orgId`, so repositories
60	 * cannot forget it. Always spread the caller filter first.
61	 */
62	export function withOrgScope<T extends object>(
63	  actor: Actor,
64	  filter: T,
65	): T & { orgId: OrgId } {
66	  return { ...filter, orgId: actor.orgId };
67	}
 1	/**
 2	 * Session cookie access. In Next 16 `cookies()` is async — every function
 3	 * here is async for that reason, and nothing outside this module touches the
 4	 * cookie jar, so the cookie's name, flags and lifetime are stated once.
 5	 */
 6	import { cookies } from "next/headers";
 7	import { SESSION_COOKIE_NAME } from "@/schemas/session";
 8	import { resolveSession } from "@/server/services/session-service";
 9	import type { IsoTimestamp } from "@/types/common";
10	import type { SessionPrincipal } from "@/types/member";
11	import { parseIso } from "./date";
12	
13	export async function getSessionToken(): Promise<string | null> {
14	  const jar = await cookies();
15	  return jar.get(SESSION_COOKIE_NAME)?.value ?? null;
16	}
17	
18	/**
19	 * The signed-in principal, or `null` when there is no cookie, the token is
20	 * unknown, or the session has expired. Callers that need a hard failure use
21	 * `getActor()` in `@/lib/actor` instead.
22	 */
23	export async function getSessionPrincipal(): Promise<SessionPrincipal | null> {
24	  const token = await getSessionToken();
25	  if (token === null) return null;
26	
27	  const principal = await resolveSession(token);
28	  if (principal === null) return null;
29	
30	  return parseIso(principal.expiresAt).getTime() > Date.now() ? principal : null;
31	}
32	
33	export async function setSessionCookie(
34	  token: string,
35	  expiresAt: IsoTimestamp,
36	): Promise<void> {
37	  const jar = await cookies();
38	  jar.set(SESSION_COOKIE_NAME, token, {
39	    httpOnly: true,
40	    sameSite: "lax",
41	    secure: process.env.NODE_ENV === "production",
42	    path: "/",
43	    expires: parseIso(expiresAt),
44	  });
45	}
46	
47	export async function clearSessionCookie(): Promise<void> {
48	  const jar = await cookies();
49	  jar.delete(SESSION_COOKIE_NAME);
50	}

