    12	import { notFound } from "next/navigation";
    13	import type { Metadata } from "next";
    14	import { PENDING_MEMBER_ID } from "@/actions/_lib/permission-resources";
    15	import { InvitationList } from "@/components/domain/member/invitation-list";
    16	import { EmptyState } from "@/components/ui/empty-state";
    17	import { can } from "@/lib/permissions";
    18	import { listPendingInvitations } from "@/server/repositories/invitation-repository";
    19	import { revokeInvitation } from "@/server/services/invitation-service";
    20	import type { InvitationId } from "@/types/common";
    21	import { loadTenantContext } from "../../../_lib/tenant-context";
    22	
    23	type PageParams = { orgSlug: string };
    24	
    25	export const dynamic = "force-dynamic";
    26	
    27	export const metadata: Metadata = {
    28	  title: "Pending invitations",
    29	};
    30	
    31	export default async function Page(props: {
    32	  params: Promise<PageParams>;
    33	  searchParams: Promise<Record<string, string | string[] | undefined>>;
    34	}) {
    35	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
    36	  const { orgSlug } = await props.params;
    37	  await props.searchParams;
    38	
    39	  const { org, actor } = await loadTenantContext(orgSlug);
    40	
    41	  const mayRead = can(actor, "member:read", {
    42	    kind: "member",
    43	    orgId: org.id,
    44	    memberId: PENDING_MEMBER_ID,
    45	    targetUserId: actor.userId,
    46	    targetRole: actor.role,
    47	  });
    48	  if (!mayRead) {
    49	    notFound();
    50	  }
    51	
    52	  const invitations = await listPendingInvitations(org.id);
    53	
    54	  async function revoke(invitationId: InvitationId): Promise<void> {
    55	    "use server";
    56	    await revokeInvitation(actor, invitationId);
    57	  }
    58	
    59	  return (
    60	    <div className="space-y-8">
    61	      <header>
    62	        <h1 className="text-xl font-semibold tracking-tight">
    63	          Pending invitations
    64	        </h1>
    65	        <p className="mt-1 text-sm text-slate-600">
    66	          Invitations that have been sent but not yet accepted. Each one still
    67	          counts against the seat quota.
    68	        </p>
    69	      </header>
    70	
    71	      {invitations.length === 0 ? (
    72	        <EmptyState
    73	          title="No invitations outstanding"
    74	          description="Everybody who was invited has either joined or been revoked."
    75	        />
    76	      ) : (
    77	        <InvitationList
    78	          invitations={invitations}
    79	          actor={actor}
    80	          onRevoke={revoke}
    81	        />
    82	      )}
    83	    </div>
    84	  );
    85	}
