    24	
    25	export type InvitationListProps = {
    26	  invitations: readonly Invitation[];
    27	  actor: Actor;
    28	  onRevoke: (invitationId: InvitationId) => void;
    29	  onResend?: (invitationId: InvitationId) => void;
    30	};
    31	
    32	/** Neither accepted nor revoked, and not past its expiry. */
    33	export function isPending(invitation: Invitation, now = new Date()): boolean {
    34	  return (
    35	    invitation.acceptedAt === null &&
    36	    invitation.revokedAt === null &&
    37	    new Date(invitation.expiresAt).getTime() > now.getTime()
    38	  );
    39	}
    40	
    41	export function InvitationList(
    42	  props: InvitationListProps,
    43	): ReactElement | null {
    44	  const { invitations, actor, onRevoke, onResend } = props;
    45	
    46	  // Revoking an invitation is the same grant as issuing one.
    47	  const mayManage = can(
    48	    actor,
    49	    "member:invite",
    50	    organizationResource(actor.orgId),
    51	  );
    52	
    53	  const pending = invitations.filter((invitation) => isPending(invitation));
    54	  if (pending.length === 0) {
    55	    return (
    56	      <EmptyState
    57	        title="No pending invitations"
    58	        description="Invitations you send appear here until they are accepted."
    59	      />
    60	    );
    61	  }
    62	
    63	  return (
    64	    <Table caption="Pending invitations">
    65	      <TableHead>
    66	        <TableRow>
    67	          <TableHeaderCell>Email</TableHeaderCell>
    68	          <TableHeaderCell>Role</TableHeaderCell>
    69	          <TableHeaderCell>Expires</TableHeaderCell>
    70	          <TableHeaderCell></TableHeaderCell>
    71	        </TableRow>
    72	      </TableHead>
    73	      <TableBody>
    74	        {pending.map((invitation) => (
    75	          <TableRow key={invitation.id}>
    76	            <TableCell>{invitation.email}</TableCell>
    77	            <TableCell className="w-32">
    78	              <RoleBadge role={invitation.role} />
    79	            </TableCell>
    80	            <TableCell className="w-40 text-sm text-neutral-500">
    81	              <Badge tone="neutral" size="sm">
    82	                {formatRelative(invitation.expiresAt)}
    83	              </Badge>
    84	            </TableCell>
    85	            <TableCell className="w-52 text-right">
    86	              {mayManage ? (
    87	                <span className="flex justify-end gap-1">
    88	                  {onResend !== undefined ? (
    89	                    <Button
    90	                      variant="ghost"
    91	                      size="sm"
    92	                      onClick={() => onResend(invitation.id)}
    93	                    >
    94	                      Resend
    95	                    </Button>
    96	                  ) : null}
    97	                  <Button
    98	                    variant="danger"
